-- Initial data from versioned GameVerse sources. Not a dump of the Beget database.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS games(id VARCHAR(80) PRIMARY KEY,title VARCHAR(160) NOT NULL,genre VARCHAR(60) NOT NULL,platforms VARCHAR(160) NOT NULL,year SMALLINT NOT NULL,rating DECIMAL(2,1) NOT NULL,tag VARCHAR(80) NOT NULL) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS news(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(16) NOT NULL,parent_id INT NULL,author VARCHAR(60) NOT NULL,title VARCHAR(160) NOT NULL DEFAULT '',body TEXT NOT NULL,host_hash CHAR(64) NOT NULL,visible BOOLEAN NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES messages(id) ON DELETE CASCADE) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS blocked_words(id INT AUTO_INCREMENT PRIMARY KEY,phrase VARCHAR(100) UNIQUE NOT NULL) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS blocked_hosts(host_hash CHAR(64) PRIMARY KEY) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS ratings(game_id VARCHAR(80),visitor VARCHAR(64),score TINYINT NOT NULL,PRIMARY KEY(game_id,visitor),FOREIGN KEY(game_id) REFERENCES games(id) ON DELETE CASCADE) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS votes(visitor VARCHAR(64) PRIMARY KEY,choice VARCHAR(30) NOT NULL) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS visits(id BIGINT AUTO_INCREMENT PRIMARY KEY,page VARCHAR(180) NOT NULL,visitor VARCHAR(64) NOT NULL,visited_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(visited_at),INDEX(page)) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits(bucket CHAR(64),slot BIGINT,hits INT NOT NULL,PRIMARY KEY(bucket,slot)) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS cache(cache_key VARCHAR(60) PRIMARY KEY,payload MEDIUMBLOB NOT NULL,updated_at DATETIME NOT NULL) CHARACTER SET utf8mb4;

CREATE TABLE IF NOT EXISTS steam_pulse_sources(app_id INT PRIMARY KEY,players INT NULL,sampled_at DATETIME NULL,attempted_at DATETIME NULL) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS steam_pulse_samples(app_id INT NOT NULL,sampled_at DATETIME NOT NULL,players INT NOT NULL,PRIMARY KEY(app_id,sampled_at)) CHARACTER SET utf8mb4;
