INSERT INTO news(title,body) SELECT 'В GameVerse появился расширенный каталог','В каталоге собраны 20 игр разных жанров. Фильтры помогают сравнить платформы, год первого выпуска и редакционные оценки. Оценки отражают мнение редакции, а не агрегированный рейтинг других сайтов.' WHERE NOT EXISTS (SELECT 1 FROM news WHERE title='В GameVerse появился расширенный каталог');
INSERT INTO news(title,body) SELECT 'Как выбрать игру для совместного вечера','Начните с количества игроков и доступных устройств. Проверьте, нужен ли отдельный экземпляр игры каждому участнику. Для локального кооператива заранее подключите контроллеры и проверьте поддержку совместной игры.' WHERE NOT EXISTS (SELECT 1 FROM news WHERE title='Как выбрать игру для совместного вечера');
INSERT INTO news(title,body) SELECT 'Игровой бюджет: считаем заранее','Сравнивайте полную стоимость покупки, включая дополнения и комиссии. Новый калькулятор GameVerse пересчитывает введённую сумму по официальным курсам Банка России. Доступность покупки и фактический курс магазина проверяются отдельно.' WHERE NOT EXISTS (SELECT 1 FROM news WHERE title='Игровой бюджет: считаем заранее');
